pub fn strip_comment(text: &str) -> String {
    const MARKER_OPEN: &str = "<!-- ─── COPY FROM HERE ─── -->";
    const MARKER_CLOSE: &str = "<!-- ─── COPY TO HERE ─── -->";
    if let Some(start) = text.find(MARKER_OPEN) {
        let body_start = start + MARKER_OPEN.len();
        let body_end = text[body_start..]
            .find(MARKER_CLOSE)
            .map(|i| body_start + i)
            .unwrap_or(text.len());
        text[body_start..body_end].trim().to_string() + "\n"
    } else {
        text.to_string()
    }
}

fn placeholder_tokens(text: &str) -> Vec<String> {
    let mut tokens = BTreeSet::new();
    for line in prose_lines(text).into_iter().map(|line| line.text) {
        let mut in_inline_code = false;
        let chars: Vec<char> = line.chars().collect();
        let mut index = 0;
        while index < chars.len() {
            if chars[index] == '`' {
                in_inline_code = !in_inline_code;
                index += 1;
                continue;
            }
            if !in_inline_code && chars[index] == '<' {
                if let Some(offset) = chars[index + 1..].iter().position(|ch| *ch == '>') {
                    let end = index + 1 + offset;
                    let inner: String = chars[index + 1..end].iter().collect();
                    let trimmed = inner.trim();
                    if !trimmed.is_empty()
                        && !trimmed.starts_with('!')
                        && !trimmed.starts_with('/')
                        && !matches!(trimmed, "br" | "details" | "summary")
                    {
                        tokens.insert(format!("<{trimmed}>"));
                    }
                    index = end + 1;
                    continue;
                }
            }
            index += 1;
        }
    }
    // A standalone placeholder with spaces can be parsed as an HTML block.
    // Inspect only the block's first node, so examples inside <pre> stay code.
    let mut html_block_start = None;
    for (event, range) in Parser::new(text).into_offset_iter() {
        match event {
            Event::Start(Tag::HtmlBlock) => html_block_start = Some(range.start),
            Event::Html(raw) if html_block_start == Some(range.start) => {
                let trimmed = raw.trim();
                if let Some(inner) = trimmed.strip_prefix('<').and_then(|v| v.strip_suffix('>')) {
                    if inner.chars().any(char::is_whitespace)
                        && !inner.contains(['<', '>', '=', '/', '!'])
                    {
                        tokens.insert(format!("<{inner}>"));
                    }
                }
            }
            Event::End(TagEnd::HtmlBlock) => html_block_start = None,
            _ => {}
        }
    }
    tokens.into_iter().collect()
}

fn check_gitignore(root: &Path) -> Check {
    let p = root.join(".gitignore");
    let body = match read_project_text(root, &p) {
        Ok(Some(body)) => body,
        Ok(None) => {
            return Check {
                name: "gitignore",
                status: Status::Warn,
                message: "no .gitignore at project root".into(),
                hint: Some(
                    "add `.mastermind/` to .gitignore — the index + specs are local state".into(),
                ),
            }
        }
        Err(error) => {
            return Check {
                name: "gitignore",
                status: Status::Warn,
                message: format!("cannot safely inspect .gitignore: {error}"),
                hint: Some("use a regular UTF-8 .gitignore no larger than 1 MiB".into()),
            }
        }
    };
    let lines: Vec<&str> = body
        .lines()
        .map(|l| l.trim())
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .collect();
    let mentioned = lines.iter().any(|l| {
        *l == ".mastermind" || *l == ".mastermind/" || *l == "/.mastermind" || *l == "/.mastermind/"
    });
    if mentioned {
        Check {
            name: "gitignore",
            status: Status::Ok,
            message: ".mastermind/ excluded".into(),
            hint: None,
        }
    } else {
        Check {
            name: "gitignore",
            status: Status::Warn,
            message: ".mastermind/ NOT in .gitignore".into(),
            hint: Some(
                "add `.mastermind/` to .gitignore — leaking the local index pollutes commits"
                    .into(),
            ),
        }
    }
}

fn npm_launcher_entry(platform: NpmLauncherPlatform, command: &str, args: Vec<String>) -> Value {
    match platform {
        NpmLauncherPlatform::Other => json!({
            "command": command,
            "args": args,
        }),
        NpmLauncherPlatform::Windows => {
            // npm executables are command shims on Windows, which cannot be
            // launched directly by every MCP client. Disable cmd AutoRun hooks
            // and use its stable /s /c parsing path for the shim.
            let mut shell_args = vec!["/d".into(), "/s".into(), "/c".into(), command.into()];
            shell_args.extend(args);
            json!({
                "command": "cmd.exe",
                "args": shell_args,
            })
        }
    }
}

pub(super) fn parse_numstat(
    raw: &str,
    is_source: impl Fn(&str) -> bool,
    is_generated: impl Fn(&str) -> bool,
) -> HashMap<String, CommitShape> {
    let mut shapes: HashMap<String, CommitShape> = HashMap::new();
    let mut current: Option<String> = None;
    for line in raw.lines() {
        if let Some(sha) = line.strip_prefix('\u{1e}') {
            let sha = sha.trim().to_string();
            shapes.insert(sha.clone(), CommitShape::default());
            current = Some(sha);
            continue;
        }
        let Some(shape) = current.as_ref().and_then(|sha| shapes.get_mut(sha)) else {
            continue;
        };
        let mut columns = line.splitn(3, '\t');
        let (Some(added), Some(_), Some(path)) = (columns.next(), columns.next(), columns.next())
        else {
            continue;
        };
        let added = added.parse::<usize>().unwrap_or(0);
        shape.files += 1;
        shape.added += added;
        if let (Some(language), false) = (range::language(path), is_generated(path)) {
            shape.languages.insert(language);
            shape.areas.insert(range::area(path));
        }
        if is_test_path(path) {
            shape.test_files += 1;
        } else if is_doc_path(path) {
            shape.doc_files += 1;
        } else if is_source(path) {
            shape.source_files += 1;
            shape.source_added += added;
        }
    }
    shapes
}

pub(super) fn area(path: &str) -> String {
    let mut parts = path.split('/');
    let first = parts.next().unwrap_or(path);
    let second = parts.next();
    let area = match (second, parts.next()) {
        (None, _) => return "(root)".to_string(),
        (Some(second), Some(_)) if CONTAINERS.contains(&first) => format!("{first}/{second}"),
        _ => first.to_string(),
    };
    if inert(&area) {
        area
    } else {
        "(other)".to_string()
    }
}

fn normalize_git_remote(remote: &str) -> Option<String> {
    let remote = remote.trim();
    let (host, path) = if let Some((scheme, rest)) = remote.split_once("://") {
        if !matches!(scheme, "https" | "http" | "ssh" | "git") {
            return None;
        }
        let (authority, path) = rest.split_once('/')?;
        (authority.rsplit('@').next()?, path)
    } else {
        let (authority, path) = remote.split_once(':')?;
        if authority.contains('/') {
            return None;
        }
        (authority.rsplit('@').next()?, path)
    };
    let host = host.to_ascii_lowercase();
    let path = path.trim_matches('/').trim_end_matches(".git");
    let path = if host == "github.com" {
        path.to_ascii_lowercase()
    } else {
        path.to_string()
    };
    if host.is_empty()
        || path.is_empty()
        || host.contains(|c: char| c.is_whitespace())
        || path.chars().any(|ch| matches!(ch, '?' | '#' | '\\'))
    {
        return None;
    }
    Some(format!("{host}/{path}"))
}

fn path_literals(prompt: &str, root: &Path) -> Vec<String> {
    let mut paths = BTreeSet::new();
    // Keep quoted paths containing spaces intact, then examine plain tokens.
    let candidates =
        prompt
            .split('`')
            .skip(1)
            .step_by(2)
            .chain(prompt.split('`').step_by(2).flat_map(|part| {
                part.split(|ch: char| {
                    ch.is_whitespace()
                        || matches!(
                            ch,
                            '`' | '"'
                                | '\''
                                | '('
                                | ')'
                                | '['
                                | ']'
                                | '{'
                                | '}'
                                | '<'
                                | '>'
                                | ','
                                | ';'
                        )
                })
            }));
    for candidate in candidates {
        if let Some(path) = relative_path(candidate, root) {
            paths.insert(path);
            if paths.len() == MAX_PATHS {
                break;
            }
        }
    }
    paths.into_iter().collect()
}

pub(super) fn quote_is_user_prose(text: &str, quote: &str) -> bool {
    let excluded = excluded_ranges(text);
    let native_attachment = [
        "# Files pasted by the user:",
        "# Files mentioned by the user:",
    ]
    .iter()
    .any(|prefix| text.trim_start().starts_with(prefix));
    let request_start = if native_attachment {
        const REQUEST_MARKER: &str = "\n## My request:";
        let mut markers = text.match_indices(REQUEST_MARKER);
        let Some((start, _)) = markers.next() else {
            return false;
        };
        // A document can itself contain this heading. Text-only envelopes do
        // not authenticate which of several occurrences belongs to the host.
        if markers.next().is_some() {
            return false;
        }
        start + REQUEST_MARKER.len()
    } else {
        0
    };
    !quote.is_empty()
        && text.match_indices(quote).any(|(start, _)| {
            let end = start + quote.len();
            // Bind the section boundary and prose checks to this exact occurrence.
            // An attachment occurrence must not validate a duplicate that appears
            // only inside code or a quotation in the user's request.
            start >= request_start
                && !excluded
                    .iter()
                    .any(|range| range.start < end && start < range.end)
        })
}

pub(crate) fn supersede_feedback(
    &mut self,
    old: &str,
    new: &str,
    old_revision: &str,
    new_revision: &str,
) -> SqlResult<SupersessionReceipt> {
    if old == new {
        return Err(invalid("a preference cannot supersede itself"));
    }
    if !super::super::collection::valid_id(old_revision)
        || !super::super::collection::valid_id(new_revision)
    {
        return Err(invalid(
            "both review revisions must be full 64-character keys",
        ));
    }
    let tx = self
        .conn
        .transaction_with_behavior(TransactionBehavior::Immediate)?;
    if let Some(receipt) = committed_receipt(&tx, old, new, old_revision, new_revision)? {
        return Ok(receipt);
    }
    let entries = preferences::read_feedback(&tx)?;
    let old_entry = entries
        .iter()
        .find(|entry| entry.key == old)
        .ok_or_else(|| invalid("old preference missing"))?;
    let new_entry = entries
        .iter()
        .find(|entry| entry.key == new)
        .ok_or_else(|| invalid("new preference missing"))?;
    if old_entry.review_revision() != old_revision
        || new_entry.review_revision() != new_revision
    {
        return Err(invalid(
            "review revision changed; inspect both preferences again",
        ));
    }
    if old_entry.category != new_entry.category || old_entry.scope != new_entry.scope {
        return Err(invalid("replacement requires the same category and scope"));
    }
    for entry in [old_entry, new_entry] {
        if !matches!(entry.status.as_str(), "candidate" | "active")
            || entry.superseded_by.is_some()
        {
            return Err(invalid(
                "rejected or superseded preferences cannot take part in a new replacement",
            ));
        }
    }
    // Each old node has at most one outgoing edge. Both endpoints must
    // currently have none, and self-links are forbidden, so an insertion
    // cannot close a cycle. There is no unbounded ancestry traversal.
    let bound: bool = tx.query_row("SELECT EXISTS(SELECT 1 FROM persona_candidate_feedback p WHERE feedback_key=?1
        AND NOT EXISTS(SELECT 1 FROM persona_feedback_dismissal d WHERE d.candidate_id=p.candidate_id))", [new], |r|r.get(0))?;
    if !bound {
        return Err(invalid(
            "replacement needs a currently verified strict source",
        ));
    }
    let at: i64 = tx.query_row("SELECT unixepoch()", [], |r| r.get(0))?;
    tx.execute("INSERT INTO feedback_supersession (old_key,new_key,old_revision,new_revision,reviewed_at)
        VALUES (?1,?2,?3,?4,?5)", params![old,new,old_revision,new_revision,at])?;
    tx.execute(
        "UPDATE feedback SET status='superseded' WHERE key=?1",
        [old],
    )?;
    tx.execute("DELETE FROM feedback_acceptance WHERE key=?1", [old])?;
    tx.execute("UPDATE feedback SET status='active' WHERE key=?1", [new])?;
    tx.execute("INSERT INTO feedback_acceptance(key,revision) VALUES (?1,?2) ON CONFLICT(key) DO UPDATE SET revision=excluded.revision", params![new,new_revision])?;
    for (key, event, revision) in [
        (
            old,
            format!("superseded:{}->{new}", old_entry.status),
            old_revision,
        ),
        (
            new,
            format!("supersedes:{old}:{}->active", new_entry.status),
            new_revision,
        ),
    ] {
        tx.execute("INSERT INTO feedback_review_event(key,status,at_epoch,reviewed_revision) VALUES (?1,?2,?3,?4)", params![key,event,at,revision])?;
    }
    let count: i64 = tx.query_row("SELECT count(*) FROM feedback_supersession", [], |r| {
        r.get(0)
    })?;
    if count > 20_000 {
        return Err(invalid("preference relation history exceeds 20000 rows"));
    }
    collection::check_size(&tx)?;
    tx.commit()?;
    Ok(SupersessionReceipt {
        old_key: old.into(),
        new_key: new.into(),
        old_revision: old_revision.into(),
        new_revision: new_revision.into(),
        reviewed_at: at,
        old_status: "superseded".into(),
        new_status: "active".into(),
        repeated: false,
    })
}

fn extract_module_constants(
    child: &Node,
    source: &[u8],
    pending: &mut PendingFile,
    module_index: usize,
) {
    // tree-sitter-python wraps top-level assignments in `expression_statement`.
    let assignment = match child.kind() {
        "expression_statement" => child.named_child(0),
        // Defensive: some grammar versions surface bare assignment at module scope.
        "assignment" => Some(*child),
        _ => None,
    };
    let Some(assignment) = assignment else {
        return;
    };
    if assignment.kind() != "assignment" {
        return;
    }
    // Skip augmented assignments (`+=`, etc.) — not declarations. tree-sitter-python
    // uses a distinct `augmented_assignment` node, so this is mostly redundant —
    // defensive against grammar shifts.
    let Some(left) = assignment.child_by_field_name("left") else {
        return;
    };
    if assignment.child_by_field_name("right").is_none() {
        // `FOO: int` with no value isn't a binding.
        return;
    }
    let signature = node_text(&assignment, source).map(|s| {
        // Single-line trimmed signature; the value preview helps grep-like search,
        // but huge dict/list literals would explode storage.
        let one_line: String = s.split('\n').next().unwrap_or(s).trim().to_string();
        if one_line.len() > 120 {
            // Walk back to a UTF-8 char boundary — slicing at a fixed byte 120
            // panics inside a multi-byte char (e.g. CJK constants like
            // `WYNTXT_JA = "はい、…"`). `is_char_boundary` is O(1) and walks back
            // at most 3 bytes (max UTF-8 code-point length is 4).
            let mut end = 120;
            while end > 0 && !one_line.is_char_boundary(end) {
                end -= 1;
            }
            format!("{}…", &one_line[..end])
        } else {
            one_line
        }
    });

    for name in collect_assignment_targets(&left, source) {
        push_def(
            pending,
            name,
            "constant",
            &assignment,
            signature.clone(),
            Some(module_index),
        );
    }
}

fn jsx_component_target(
    element: &Node,
    source: &[u8],
) -> Option<(String, Option<String>, Option<String>)> {
    let name_node = element.child_by_field_name("name")?;
    let (name, path, to_type) = leaf_and_path(&name_node, source)?;
    if starts_uppercase(&name) {
        Some((name, path, to_type))
    } else {
        None
    }
}

fn emit_include(decl: &Node, source: &[u8], pending: &mut PendingFile, module_index: usize) {
    let line = line_of(decl);
    let Some(path_node) = decl.child_by_field_name("path") else {
        return;
    };
    let raw = node_text(&path_node, source).unwrap_or("").trim();
    if raw.is_empty() {
        return;
    }
    let cleaned = raw
        .trim_start_matches(['<', '"'])
        .trim_end_matches(['>', '"']);
    // Leaf = filename without dir prefix.
    let leaf = cleaned.rsplit('/').next().unwrap_or(cleaned).to_string();
    push_import(
        pending,
        module_index,
        leaf,
        Some(format!("{cleaned}::*")),
        line,
    );
}

fn collect_use_names(
    node: &Node,
    source: &[u8],
    pending: &mut PendingFile,
    module_index: usize,
    line: u32,
    prefix: Option<&str>,
) {
    match node.kind() {
        "identifier" | "type_identifier" => {
            if let Some(name) = node_text(node, source) {
                let path = compose_scoped(prefix, name);
                push_import(pending, module_index, name.to_string(), Some(path), line);
            }
        }
        "scoped_identifier" => {
            // use foo::bar — imports "bar", path is the full scoped expression.
            let full = node_text(node, source).map(String::from);
            let leaf_path = full.as_deref().unwrap_or("");
            let combined = if let Some(p) = prefix {
                format!("{p}::{leaf_path}")
            } else {
                leaf_path.to_string()
            };
            if let Some(n) = node.child_by_field_name("name") {
                if let Some(name) = node_text(&n, source) {
                    push_import(
                        pending,
                        module_index,
                        name.to_string(),
                        Some(combined),
                        line,
                    );
                }
            }
        }
        "use_as_clause" => {
            // use foo::bar as baz — name="baz", path="foo::bar" (prefix prepended).
            let alias = node
                .child_by_field_name("alias")
                .and_then(|a| node_text(&a, source));
            let inner_path = node
                .child_by_field_name("path")
                .and_then(|p| node_text(&p, source))
                .map(String::from);

            if let Some(name) = alias {
                let path = match (prefix, inner_path) {
                    (Some(p), Some(i)) => Some(format!("{p}::{i}")),
                    (Some(p), None) => Some(p.to_string()),
                    (None, Some(i)) => Some(i),
                    (None, None) => None,
                };
                push_import(pending, module_index, name.to_string(), path, line);
            }
        }
        "use_list" | "scoped_use_list" => {
            // { a, b, c::d } — recurse into each entry. For scoped_use_list the
            // path child is the prefix, list holds entries.
            let new_prefix = if node.kind() == "scoped_use_list" {
                let local = node
                    .child_by_field_name("path")
                    .and_then(|p| node_text(&p, source));
                match (prefix, local) {
                    (Some(p), Some(l)) => Some(format!("{p}::{l}")),
                    (Some(p), None) => Some(p.to_string()),
                    (None, Some(l)) => Some(l.to_string()),
                    (None, None) => None,
                }
            } else {
                prefix.map(String::from)
            };

            let entries = if node.kind() == "scoped_use_list" {
                node.child_by_field_name("list")
            } else {
                Some(*node)
            };
            if let Some(list) = entries {
                let mut c = list.walk();
                for ch in list.children(&mut c) {
                    collect_use_names(
                        &ch,
                        source,
                        pending,
                        module_index,
                        line,
                        new_prefix.as_deref(),
                    );
                }
            }
        }
        "use_wildcard" => {
            let path = prefix
                .map(|p| format!("{p}::*"))
                .or_else(|| Some("*".to_string()));
            push_import(pending, module_index, "*".to_string(), path, line);
        }
        _ => {
            // Permissive: try the last identifier we can find.
            if let Some(name) = rightmost_identifier(node, source) {
                let path = compose_scoped(prefix, &name);
                push_import(pending, module_index, name, Some(path), line);
            }
        }
    }
}

fn resolve_cpp_include(source: &str, encoded: &str, paths: &BTreeSet<String>) -> BTreeSet<String> {
    let include = encoded
        .strip_suffix("::*")
        .unwrap_or(encoded)
        .replace('\\', "/");
    let mut resolved = BTreeSet::new();
    if let Some(path) = normalize_relative(&include) {
        if paths.contains(&path) {
            resolved.insert(path);
        }
    }
    if let Some(parent) = source.rsplit_once('/').map(|(parent, _)| parent) {
        if let Some(path) = normalize_relative(&format!("{parent}/{include}")) {
            if paths.contains(&path) {
                resolved.insert(path);
            }
        }
    }
    if resolved.is_empty() {
        let lower = include.to_ascii_lowercase();
        let basename = lower.rsplit('/').next().unwrap_or(&lower);
        for candidate in paths {
            let candidate_lower = candidate.to_ascii_lowercase();
            if candidate_lower.rsplit('/').next() == Some(basename)
                && (!lower.contains('/')
                    || candidate_lower == lower
                    || candidate_lower.ends_with(&format!("/{lower}")))
            {
                resolved.insert(candidate.clone());
            }
        }
    }
    resolved
}
